import ContextManager from "#core/ui/context-manager/context-manager.js";
import LensManager, { ILensLayer } from "#core/ui/lenses/lens-manager.js";

import { IProjectedTradeRoute, TradeRoutesModel } from "#base/ui/trade-route-chooser/trade-routes-model.js";
import { OVERLAY_PRIORITY } from "#base/ui/utilities/utilities-overlay.js";

const TRADE_RANGE_OUT_OF_RANGE_COLOR = 0x550000cd;
const TRADE_RANGE_AVAILABLE_COLOR = 0x5500cd00;
const MAX_FRAMES_TO_WAIT_FOR_INIT = 960; // At 60fps = 16 seconds

class TradeLensLayer implements ILensLayer {
	private tradeRangeOverlayGroup = WorldUI.createOverlayGroup(
		"ContinentOverlayGroup",
		OVERLAY_PRIORITY.CONTINENT_LENS,
	);
	private tradeRangeOverlay = this.tradeRangeOverlayGroup.addPlotOverlay();

	initLayer() {}

	private async initCities() {
		return new Promise((resolve) => {
			TradeRoutesModel.calculateProjectedTradeRoutes().then((routes) =>
				this.processRoutesForOverlayAsync(routes, resolve),
			);
		});
	}

	private processRoutesForOverlayAsync(routes: IProjectedTradeRoute[], doneCallback: (value: unknown) => void) {
		const outOfRangePlots: PlotIndex[] = [];
		const availableCities: PlotIndex[] = [];

		const total = routes.length;
		let index = 0;

		const processChunk = () => {
			const start = performance.now();

			// Process as many routes as we can within the frame budget
			while (index < total && performance.now() - start < MAX_FRAMES_TO_WAIT_FOR_INIT) {
				const route = routes[index++];

				const cityPlots = route.city.getPurchasedPlots();
				const plots = cityPlots.length > 0 ? cityPlots : [route.cityPlotIndex];

				if (route.status === TradeRouteStatus.SUCCESS) {
					for (const plot of plots) {
						availableCities.push(plot);
					}
				} else {
					for (const plot of plots) {
						outOfRangePlots.push(plot);
					}
				}
			}

			if (index < total) {
				// More to do, yield back to the browser and continue next frame
				requestAnimationFrame(processChunk);
			} else {
				// All routes processed – now do DOM work ONCE
				this.finishInitCities(availableCities, outOfRangePlots);
				doneCallback(index);
			}
		};

		// Kick off first chunk
		requestAnimationFrame(processChunk);
	}

	private finishInitCities(availableCities: PlotIndex[], outOfRangePlots: PlotIndex[]): void {
		// Reset & draw overlays once
		this.tradeRangeOverlayGroup.setVisible(false);
		this.tradeRangeOverlay.clear();

		this.tradeRangeOverlay.addPlots(outOfRangePlots, {
			fillColor: TRADE_RANGE_OUT_OF_RANGE_COLOR,
		});
		this.tradeRangeOverlay.addPlots(availableCities, {
			fillColor: TRADE_RANGE_AVAILABLE_COLOR,
		});

		this.tradeRangeOverlayGroup.setVisible(true);
	}

	async applyLayer() {
		await this.initCities();
		this.tradeRangeOverlayGroup.setVisible(true);
		ContextManager.push("trade-route-chooser", { singleton: true });
	}

	removeLayer() {
		this.tradeRangeOverlayGroup.clearAll();
		this.tradeRangeOverlay.clear();
		ContextManager.pop("trade-route-chooser");
	}
}

declare global {
	interface LensLayerTypeMap {
		"fxs-trade-layer": TradeLensLayer;
	}
}

LensManager.registerLensLayer("fxs-trade-layer", new TradeLensLayer());
